sys_script_include.script:
var GetAIDevicePrice = Class.create();
GetAIDevicePrice.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    type: 'GetAIDevicePrice',
    getPrice: function() {
        var deviceId = this.getParameter('sysparm_device_id');


        var gr = new GlideRecord('x_1869195_ai_device');
        if (gr.get(deviceId)) {
            return gr.u_price_2;
        }
        return '';
    }
});
